// Draws the sight lines the module actually tests, between the selected token and
// each target. Green reached its point; red hit a sight-blocking wall, is marked with
// an X where it hit, and fades away beyond it.
//
// Sight is clear if ANY one line gets through, so a mostly-red target with a single
// green line is still visible.
//
// Run it again, or move or retarget anything, to clear the overlay.
const api = game.modules.get('draw-steel-combat-tools')?.api;
if (!api?.sightLines) { ui.notifications.error('Draw Steel: Combat Tools is not active.'); return; }

if (window._dsctLosLayer && !window._dsctLosLayer.destroyed) {
  window._dsctLosLayer.destroy({ children: true });
  window._dsctLosLayer = null;
  return;
}

const src = canvas.tokens.controlled[0];
if (!src) { ui.notifications.warn('Select the token doing the looking.'); return; }

const targets = [...game.user.targets].filter(t => t !== src && !t.destroyed);
if (!targets.length) { ui.notifications.warn('Target at least one token to check sight to.'); return; }

const layer = new PIXI.Container();
layer.eventMode = 'none';
canvas.controls.addChild(layer);
window._dsctLosLayer = layer;

const CLEAR = 0x44d07a;
const BLOCK = 0xd04444;
const summary = [];

for (const tok of targets) {
  const lines = api.sightLines(src, tok);
  const clear = lines.filter(l => !l.blocked);
  const g = new PIXI.Graphics();

  // Blocked first, so a single successful line stays readable on top of the twenty
  // red ones a large token can produce.
  for (const l of lines) {
    if (!l.blocked) continue;
    const hit = l.hit;

    g.lineStyle(2, BLOCK, 0.85);
    g.moveTo(l.from.x, l.from.y);
    g.lineTo(hit.x, hit.y);

    // Past the wall the line dies out. PIXI has no gradient stroke, so it is drawn as
    // short steps with falling alpha, which reads the same at this scale.
    const STEPS = 12;
    for (let i = 0; i < STEPS; i++) {
      const a = i / STEPS, b = (i + 1) / STEPS;
      g.lineStyle(2, BLOCK, 0.5 * (1 - b));
      g.moveTo(hit.x + (l.to.x - hit.x) * a, hit.y + (l.to.y - hit.y) * a);
      g.lineTo(hit.x + (l.to.x - hit.x) * b, hit.y + (l.to.y - hit.y) * b);
    }

    // X on the blocking point, drawn square to the line so it reads at any angle.
    const len = Math.hypot(l.to.x - l.from.x, l.to.y - l.from.y) || 1;
    const ux = (l.to.x - l.from.x) / len, uy = (l.to.y - l.from.y) / len;
    const px = -uy, py = ux, R = 5;
    g.lineStyle(2.5, BLOCK, 1);
    g.moveTo(hit.x - (ux + px) * R, hit.y - (uy + py) * R);
    g.lineTo(hit.x + (ux + px) * R, hit.y + (uy + py) * R);
    g.moveTo(hit.x - (ux - px) * R, hit.y - (uy - py) * R);
    g.lineTo(hit.x + (ux - px) * R, hit.y + (uy - py) * R);
  }

  for (const l of clear) {
    g.lineStyle(3, CLEAR, 0.95);
    g.moveTo(l.from.x, l.from.y);
    g.lineTo(l.to.x, l.to.y);
    g.beginFill(CLEAR, 1);
    g.drawCircle(l.to.x, l.to.y, 3);
    g.endFill();
  }
  layer.addChild(g);

  const visible = clear.length > 0;
  const label = new PIXI.Text(`${visible ? 'SEEN' : 'BLOCKED'}  ${clear.length}/${lines.length}`, {
    fontFamily: 'Signika, sans-serif', fontSize: 20, fontWeight: 'bold',
    fill: visible ? 0xbdffd6 : 0xffc0c0, stroke: 0x000000, strokeThickness: 5,
  });
  label.anchor.set(0.5, 1);
  label.position.set(tok.center.x, tok.y - 6);
  layer.addChild(label);

  summary.push(`${tok.name}: ${visible ? 'visible' : 'blocked'} (${clear.length}/${lines.length} clear)`);
}

ui.notifications.info(`Line of sight from ${src.name} - ${summary.join(' | ')}`);

// Clear on the next move, selection change or retarget, so it never goes stale.
const off = () => {
  if (window._dsctLosLayer && !window._dsctLosLayer.destroyed) {
    window._dsctLosLayer.destroy({ children: true });
    window._dsctLosLayer = null;
  }
  Hooks.off('updateToken', off);
  Hooks.off('controlToken', off);
  Hooks.off('targetToken', off);
};
Hooks.on('updateToken', off);
Hooks.on('controlToken', off);
Hooks.on('targetToken', off);
